import React, { useState } from "react";
import axios from "axios";
import "./Login.scss";
import { getBaseURL } from "../apiConfig";

function Login(props) {
  let [uname, setUname] = useState("");
  let [password, setPass] = useState("");
  let [error, setError] = useState("");

  // Adding click handler
  function handleClick() {
    if (validateInputs()) {
      const user = {
        email: uname,
        password: password,
      };
      let url = `${getBaseURL()}api/users/login`;
      axios
        .post(url, { ...user })
        .then((res) => {
          console.log(res);
          if (res.data.length > 0) {
            console.log("Logged in successfully");
  
            // Stockage des informations utilisateur dans sessionStorage
            const userData = {
              userId: res.data[0].userId, // Récupérez l'ID utilisateur
              isAdmin: res.data[0].isAdmin, // Récupérez le rôle (1 ou 2)
            };
  
            // Stocker les informations utilisateur complètes
            sessionStorage.setItem("isUserAuthenticated", true);
            sessionStorage.setItem("customerId", userData.userId);
            sessionStorage.setItem("user", JSON.stringify(userData));
  
            // Mettre à jour l'état d'authentification
            props.setUserAuthenticatedStatus(userData.isAdmin === 1, userData.userId);
          } else {
            console.log("User not available");
            setError("Invalid email or password.");
          }
        })
        .catch((err) => {
          console.log(err);
          console.log("Error during login.");
          setError("An error occurred during login. Please try again.");
        });
    }
  }
  
  // Function to validate email format
  function validateEmail(email) {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return regex.test(email);
  }

  // Function to validate password length
  function validatePassword(password) {
    return password.length >= 6;
  }

  // Function to validate inputs
  function validateInputs() {
    if (!validateEmail(uname)) {
      setError("Please provide a valid email address.");
      return false;
    } else if (!validatePassword(password)) {
      setError("Password must be at least 6 characters long.");
      return false;
    }
    setError("");
    return true;
  }

  // Function to handle changes in email input
  function changeName(event) {
    setUname(event.target.value);
  }

  // Function to handle changes in password input
  function changePass(event) {
    setPass(event.target.value);
  }

  return (
    <>
      <div className="login-container">
        <h1>Login</h1>
        <div>
          <label>E-Mail</label>
          <input type="text" value={uname} onChange={changeName}></input>
        </div>
        <div>
          <label>Password</label>
          <input
            type="password"
            value={password}
            onChange={changePass}
          ></input>
        </div>
        {error && <div className="error-message">{error}</div>}
        <button onClick={handleClick}>Login</button>
        <div className="register-link" onClick={() => props.navigateToRegisterPage()}>
          Is New User
        </div>
      </div>
    </>
  );
}

export default Login;
